(5094102, 743165, 87808, '<td valign="top">Interesting.  It is in focus</td>', 'Interesting.  It is in focus', '2008-12-01 10:48:09.000000', NULL, 1),
(5094103, 743181, 96915, '<td valign="top">background is a bit distracting and the crop is too tight.</td>', 'background is a bit distracting and the crop is too tight.', '2008-12-01 10:48:20.000000', NULL, 1),
(5094105, 742335, 87808, '<td valign="top">Nicely done, very crisp and clear light, fabulous colours, It is a shame though about the hand, I wish I could see more detail.8</td>', 'Nicely done, very crisp and clear light, fabulous colours, It is a shame though about the hand, I wish I could see more detail.8', '2008-12-01 10:48:56.000000', NULL, 1),
(5094107, 743467, 93543, '<td valign="top">Incredible. 10. I would be interested in hearing how it was done.</td>', 'Incredible. 10. I would be interested in hearing how it was done.', '2008-12-01 10:49:17.000000', NULL, 1),
(5094109, 742899, 87808, '<td valign="top">Very clever, a tad bit more sharpness in the glasses would have been great, but you did an excellent job</td>', 'Very clever, a tad bit more sharpness in the glasses would have been great, but you did an excellent job', '2008-12-01 10:50:03.000000', NULL, 1),
(5094112, 743024, 87808, '<td valign="top">Made me chuckle, great expression on her face, that makes the shot.  Crisp clean cut lines and nicely focused.  Well done 9</td>', 'Made me chuckle, great expression on her face, that makes the shot.  Crisp clean cut lines and nicely focused.  Well done 9', '2008-12-01 10:50:48.000000', NULL, 1),
(5094114, 743671, 87808, '<td valign="top">Well done on your focus, sharp and clean throughout.</td>', 'Well done on your focus, sharp and clean throughout.', '2008-12-01 10:51:43.000000', NULL, 1),
(5094128, 741560, 31535, '<td valign="top">Terrific shot tim. I had the same idea, but due to it being the rainy season in Vancouver, I could not shoot it. Seems my wife didn''t want me to play with fire indoors. 9 from me.</td>', 'Terrific shot tim. I had the same idea, but due to it being the rainy season in Vancouver, I could not shoot it. Seems my wife didn''t want me to play with fire indoors. 9 from me.', '2008-12-01 10:56:41.000000', NULL, 1),
(5094131, 743601, 56109, '<td valign="top">At first, I thought that it might be cool if the eye was red, but after much consideration, I like it as is. Great shot.</td>', 'At first, I thought that it might be cool if the eye was red, but after much consideration, I like it as is. Great shot.', '2008-12-01 10:58:43.000000', NULL, 1),
(5094132, 742971, 56109, '<td valign="top">haha, that guys expression.</td>', 'haha, that guys expression.', '2008-12-01 10:59:07.000000', NULL, 1),
(5094134, 743467, 56109, '<td valign="top">The winner imo.</td>', 'The winner imo.', '2008-12-01 10:59:51.000000', NULL, 1),
(5094138, 742581, 56109, '<td valign="top">LOL. That is sooo damn funny! I''ve looked at this picture probably 10 times and get a laugh every time. Love the caption (Does it work?).</td>', 'LOL. That is sooo damn funny! I''ve looked at this picture probably 10 times and get a laugh every time. Love the caption (Does it work?).', '2008-12-01 11:01:32.000000', NULL, 1),
