(5094159, 742683, 44825, '<td valign="top">I don''t know how you did this but I like it.</td>', 'I don''t know how you did this but I like it.', '2008-12-01 11:05:55.000000', NULL, 1),
(5094238, 742581, 100387, '<td valign="top">This made me laugh ... great lighting and interesting subject</td>', 'This made me laugh ... great lighting and interesting subject', '2008-12-01 11:23:27.000000', NULL, 1),
(5094249, 743467, 100387, '<td valign="top">I love the use of color and composition .... it really brings the viewer in</td>', 'I love the use of color and composition .... it really brings the viewer in', '2008-12-01 11:24:36.000000', NULL, 1),
(5094255, 743109, 100387, '<td valign="top">I like the position of the woman and her expression. Her hand is a bit awkward in the positioning and in relation to her body. I am interested in how you made this image it is one of my favorite!</td>', 'I like the position of the woman and her expression. Her hand is a bit awkward in the positioning and in relation to her body. I am interested in how you made this image it is one of my favorite!', '2008-12-01 11:30:29.000000', NULL, 1),
(5094308, 743706, 71239, '<td valign="top">It would be easy to think - "yeah I could of thought of that and it would be easy to do so 5 or 6 as a score" - but starting with "elasticity" as a subject and getting to here is a great creative leap.  The liquid has just the right amount of ooze to make the hand blend into the pool too.  great job and 9.</td>', 'It would be easy to think - "yeah I could of thought of that and it would be easy to do so 5 or 6 as a score" - but starting with "elasticity" as a subject and getting to here is a great creative leap.  The liquid has just the right amount of ooze to make the hand blend into the pool too.  great job and 9.', '2008-12-01 12:01:42.000000', NULL, 1),
(5094326, 741560, 71239, '<td valign="top">Dramatic and perfectly staged.  Great facial expression complements the shot.  Top of the heap and 10.</td>', 'Dramatic and perfectly staged.  Great facial expression complements the shot.  Top of the heap and 10.', '2008-12-01 12:04:02.000000', NULL, 1),
(5094344, 743024, 71239, '<td valign="top">Hair, expression and cutlery all spot on.  Bonus points for humour and creativity, 9.</td>', 'Hair, expression and cutlery all spot on.  Bonus points for humour and creativity, 9.', '2008-12-01 12:09:16.000000', NULL, 1),
(5094347, 743645, 73942, '<td valign="top">cool, was this taken from a plane or helicopter</td>', 'cool, was this taken from a plane or helicopter', '2008-12-01 12:10:43.000000', NULL, 1),
(5094349, 743707, 73942, '<td valign="top">nice find</td>', 'nice find', '2008-12-01 12:10:57.000000', NULL, 1),
(5094351, 743332, 73942, '<td valign="top">I like the originality!</td>', 'I like the originality!', '2008-12-01 12:11:41.000000', NULL, 1),
(5094358, 743736, 71239, '<td valign="top">Great depth of field and just a shame that the spoon isn''t tack sharp (might have been difficult if it is falling rather than being suspended).  Simple composition but tells the story well. 8.<br/> <br/>PS I expect you to do the "desperate fight in the small toilet" scene next...</td>', 'Great depth of field and just a shame that the spoon isn''t tack sharp (might have been difficult if it is falling rather than being suspended).  Simple composition but tells the story well. 8. PS I expect you to do the "desperate fight in the small toilet" scene next...', '2008-12-01 12:13:37.000000', NULL, 1),
(5094361, 743671, 73942, '<td valign="top">love the expression but I think I would have cropped above the red pants</td>', 'love the expression but I think I would have cropped above the red pants', '2008-12-01 12:14:07.000000', NULL, 1),
(5094380, 743308, 71239, '<td valign="top">Whilst the artwork is on topic, I''m afraid I can''t rate this highly as a photograph because it just a straight copy of a single piece of artwork.  If it had any other element in there then things would be different.  Sorry.</td>', 'Whilst the artwork is on topic, I''m afraid I can''t rate this highly as a photograph because it just a straight copy of a single piece of artwork.  If it had any other element in there then things would be different.  Sorry.', '2008-12-01 12:18:47.000000', NULL, 1),
(5094386, 743202, 73942, '<td valign="top">not sure these are super powers but excellent photo, 7</td>', 'not sure these are super powers but excellent photo, 7', '2008-12-01 12:19:41.000000', NULL, 1),
(5094396, 743297, 73942, '<td valign="top">cute squirrel photo</td>', 'cute squirrel photo', '2008-12-01 12:21:55.000000', NULL, 1),
(5094399, 743534, 71239, '<td valign="top">I''ve had a look to see if this name is indeed the ordinary name of a superhero, but I couldn''t find anything.  If it was a "Dr Clark Kent" I would get the link and score higher, but without that link to the challenge I''m afraid the score suffers.<br/> <br/>Apologies in advance if I''ve missed something.</td>', 'I''ve had a look to see if this name is indeed the ordinary name of a superhero, but I couldn''t find anything.  If it was a "Dr Clark Kent" I would get the link and score higher, but without that link to the challenge I''m afraid the score suffers. Apologies in advance if I''ve missed something.', '2008-12-01 12:22:55.000000', NULL, 1),
(5094427, 742520, 71239, '<td valign="top">Plus points for great humour, but it is a self-declared shoehorn...<br/> <br/>Like the image outside of any challenge constraints though.</td>', 'Plus points for great humour, but it is a self-declared shoehorn... Like the image outside of any challenge constraints though.', '2008-12-01 12:28:06.000000', NULL, 1),
(5094439, 743645, 71239, '<td valign="top">Nice idea, but a pity there wasn''t enough light around to get it tack sharp from the helicopter/plane.</td>', 'Nice idea, but a pity there wasn''t enough light around to get it tack sharp from the helicopter/plane.', '2008-12-01 12:29:30.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5094596, 743616, 58380, '<td valign="top">haha did you shoot this and masters at the same time? the lighting in both looks cool.</td>', 'haha did you shoot this and masters at the same time? the lighting in both looks cool.', '2008-12-01 13:06:59.000000', NULL, 1),
(5094648, 742732, 100393, '<td valign="top">That''s an interesting shield effect.</td>', 'That''s an interesting shield effect.', '2008-12-01 13:22:16.000000', NULL, 1),
(5094652, 743485, 100393, '<td valign="top">I don''t know how you''ve done this and stayed within the editing rules - good job with that.<br/> <br/>The face is a bit over-processed; it looks over sharp and over noise reduced; and the orange glow it a bit too uneven. These are a bit at odds with the rest of the execution which is excellent.</td>', 'I don''t know how you''ve done this and stayed within the editing rules - good job with that. The face is a bit over-processed; it looks over sharp and over noise reduced; and the orange glow it a bit too uneven. These are a bit at odds with the rest of the execution which is excellent.', '2008-12-01 13:23:02.000000', NULL, 1),
(5094653, 743725, 100393, '<td valign="top">Clever pic - though for this challenge, I think the strings kind of ruin the effect, making them disappear would have been a neater trick than to accentuate them.</td>', 'Clever pic - though for this challenge, I think the strings kind of ruin the effect, making them disappear would have been a neater trick than to accentuate them.', '2008-12-01 13:23:12.000000', NULL, 1),
(5094654, 743779, 100393, '<td valign="top">This works really well.</td>', 'This works really well.', '2008-12-01 13:23:16.000000', NULL, 1),
(5094655, 742683, 100393, '<td valign="top">Excellent concept and well done too - it looks a bit like the Spiderman half should be a bit smaller though, as it appears as if the top of the head would be at different heights for each half.</td>', 'Excellent concept and well done too - it looks a bit like the Spiderman half should be a bit smaller though, as it appears as if the top of the head would be at different heights for each half.', '2008-12-01 13:23:24.000000', NULL, 1),
