(5094658, 742520, 100393, '<td valign="top">At least you are honest - the irony is, I think the shoehorn award might go elsewhere!</td>', 'At least you are honest - the irony is, I think the shoehorn award might go elsewhere!', '2008-12-01 13:24:28.000000', NULL, 1),
(5094659, 743638, 100393, '<td valign="top">Funny!</td>', 'Funny!', '2008-12-01 13:24:32.000000', NULL, 1),
