INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5124639, 743706, 73564, '<td valign="top">it slimed off as easily it slimed on.....really goo-y goo.</td>', 'it slimed off as easily it slimed on.....really goo-y goo.', '2008-12-11 09:53:47.000000', NULL, 0),
(5124928, 743132, 80096, '<td valign="top">I know you''re allowed to darken a background by using the burn tool, which I have done on several occasions. It removes subtle lights/colors in the background almost entirely and evidently that''s ok. What you did was to create light areas in the background that didn''t exist in the original. It was a good idea but evidently not acceptable. Next time, use a sky/cloud backdrop, I''ve seen these things in the craft stores. <br/> <br/>I like what you did though, it''s very original. Keep up the good work!</td>', 'I know you''re allowed to darken a background by using the burn tool, which I have done on several occasions. It removes subtle lights/colors in the background almost entirely and evidently that''s ok. What you did was to create light areas in the background that didn''t exist in the original. It was a good idea but evidently not acceptable. Next time, use a sky/cloud backdrop, I''ve seen these things in the craft stores.  I like what you did though, it''s very original. Keep up the good work!', '2008-12-11 12:36:29.000000', NULL, 0),
(5125294, 743132, 68947, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by digifotojo:</b></div><hr/><i> I know you''re allowed to darken a background by using the burn tool, which I have done on several occasions. It removes subtle lights/colors in the background almost entirely and evidently that''s ok. What you did was to create light areas in the background that didn''t exist in the original. It was a good idea but evidently not acceptable. Next time, use a sky/cloud backdrop, I''ve seen these things in the craft stores. <br/> <br/>I like what you did though, it''s very original. Keep up the good work! </i></td></tr></table> <br/> <br/>I see your point Jo and thank you for the compliment! :)<br/> <br/>Actually, though.... the ORIGINAL background was "light".  It was a lighter blue with light and dark areas to it due to lighting.  What I did was to darken the background by using levels, color balance, H&amp;S, brightness and contrast to the OVERALL shot both in RAW conversion and then again in Photoshop.  <br/> <br/>The DODGE tool was used to bring back out the ORIGINAL background lightness and color.  I did not use the burn tool to darken the background, which could have worked too.  Perhaps, had I done it that way, it would have been legal but, I doubt it. <br/> <br/>Anyways, it''s a moot point now.  No need in going over it all again since it was DQ''d and that is that.<br/><br/><i>Message edited by author 2008-12-11 15:01:38.</i></td>', 'Originally posted by digifotojo: I know you''re allowed to darken a background by using the burn tool, which I have done on several occasions. It removes subtle lights/colors in the background almost entirely and evidently that''s ok. What you did was to create light areas in the background that didn''t exist in the original. It was a good idea but evidently not acceptable. Next time, use a sky/cloud backdrop, I''ve seen these things in the craft stores.  I like what you did though, it''s very original. Keep up the good work!   I see your point Jo and thank you for the compliment! :) Actually, though.... the ORIGINAL background was "light".  It was a lighter blue with light and dark areas to it due to lighting.  What I did was to darken the background by using levels, color balance, H&S, brightness and contrast to the OVERALL shot both in RAW conversion and then again in Photoshop.   The DODGE tool was used to bring back out the ORIGINAL background lightness and color.  I did not use the burn tool to darken the background, which could have worked too.  Perhaps, had I done it that way, it would have been legal but, I doubt it.  Anyways, it''s a moot point now.  No need in going over it all again since it was DQ''d and that is that.', '2008-12-11 14:59:41.000000', '2008-12-11 15:01:38.000000', 0),
